#!/usr/bin/env python3
"""Render the exact plotted CSVs as PNGs and interactive Vega-Lite specs.
Run in the checking repo's uv environment: python code/charts-canals-nuclear.py ENTRY.
"""
import csv,json,shutil,sys
from pathlib import Path
import vl_convert as vlc
P=Path(sys.argv[1]);C=P/'charts';C.mkdir(exist_ok=True)
BASE={'$schema':'https://vega.github.io/schema/vega-lite/v5.json','background':'#fbfaf7','config':{'font':'Arial, sans-serif','view':{'stroke':None},'axis':{'labelColor':'#343d46','titleColor':'#343d46','gridColor':'#dedfdc','labelFontSize':12,'titleFontSize':13},'legend':{'orient':'top','title':None,'labelFontSize':12,'labelLimit':450},'title':{'anchor':'start','fontSize':18,'subtitleFontSize':12,'subtitleColor':'#4b5563'}}}
def emit(name,spec,numeric):
 shutil.copy2(P/'data'/(name+'.csv'),C/(name+'.csv'))
 spec={**BASE,**spec,'data':{'url':f'charts/{name}.csv','format':{'type':'csv','parse':{k:'number' for k in numeric}}}}
 (C/(name+'.vl.json')).write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n')
 png=json.loads(json.dumps(spec));rows=list(csv.DictReader((C/(name+'.csv')).open()))
 for r in rows:
  for k in numeric:r[k]=float(r[k])
 png['data']={'values':rows};(C/(name+'.png')).write_bytes(vlc.vegalite_to_png(png,scale=2))
rows=list(csv.DictReader((P/'data/1-spending-comparison.csv').open()));order=[r['label'] for r in sorted(rows,key=lambda r:float(r['spend_gdp_pct']),reverse=True)]
emit('1-spending-comparison',{'width':490,'height':{'step':40},'title':{'text':'Canals and nuclear add smaller spending comparisons','subtitle':['Annual spending / GDP (%), with different coverage marked.','Canals: period mean, not peak. France: approximate point. AI: global-company proxy.']},'encoding':{'y':{'field':'label','type':'nominal','sort':order,'title':None,'axis':{'labelLimit':335}},'x':{'field':'spend_gdp_pct','type':'quantitative','title':'Spending / GDP (%)','scale':{'domain':[0,7]}},'tooltip':[{'field':'label','title':'Case'},{'field':'spend_gdp_pct','type':'quantitative','format':'.1f','title':'Approximate GDP share (%)'},{'field':'basis'},{'field':'qualification'}]},'layer':[{'mark':{'type':'bar','cornerRadiusEnd':2},'params':[{'name':'kindpick','select':{'type':'point','fields':['basis']},'bind':'legend'}],'encoding':{'color':{'field':'basis','type':'nominal','scale':{'domain':['Historical annual reconstruction','Partial nuclear coverage','Approximate single observation','Period mean, not annual peak','Global company proxy'],'range':['#126782','#527969','#77858a','#bc8e29','#b86412']},'legend':{'direction':'vertical'}},'opacity':{'condition':{'param':'kindpick','value':1},'value':.2}}},{'mark':{'type':'text','align':'left','dx':5,'color':'#253341'},'encoding':{'text':{'field':'spend_gdp_pct','format':'.1f'}}}]},['spend_gdp_pct'])
emit('2-canal-dividends-returns',{'width':560,'height':290,'title':{'text':'High canal dividends could overstate equity returns','subtitle':['Company means over available periods within 1770–1855 (%).','Five surviving major-company archives; not a representative national sample.']},'mark':{'type':'bar','cornerRadiusEnd':2},'params':[{'name':'returnpick','select':{'type':'point','fields':['measure']},'bind':'legend'}],'encoding':{'y':{'field':'company','type':'nominal','sort':['Birmingham','Oxford','Leeds and Liverpool','Lancaster','Kennet and Avon'],'title':None,'axis':{'labelLimit':170}},'yOffset':{'field':'measure'},'x':{'field':'percent','type':'quantitative','title':'Annual mean (%)'},'color':{'field':'measure','type':'nominal','scale':{'domain':['Return on equity','Dividend / nominal share capital'],'range':['#126782','#b86412']},'legend':{'direction':'vertical'}},'opacity':{'condition':{'param':'returnpick','value':1},'value':.2},'tooltip':[{'field':'company'},{'field':'measure'},{'field':'percent','format':'.1f'}]}},['percent'])
emit('3-nuclear-construction',{'width':600,'height':250,'title':{'text':'US nuclear construction spending fell after the early 1980s','subtitle':['Investor-owned utilities only, 1979–1990; accounting expenditure includes financing.','Public utilities and 1965–1978 are absent. This is not a complete national peak search.']},'mark':{'type':'line','point':{'filled':True,'size':45},'color':'#126782'},'encoding':{'x':{'field':'year','type':'quantitative','title':'Year','axis':{'format':'d','tickMinStep':1}},'y':{'field':'share_gdp_pct','type':'quantitative','title':'Construction accounting expenditure / GDP (%)','scale':{'domain':[0,.55]}},'tooltip':[{'field':'year'},{'field':'construction_usd_m','type':'quantitative','title':'USD million','format':',.0f'},{'field':'share_gdp_pct','type':'quantitative','title':'GDP share (%)','format':'.1f'}]}},['year','construction_usd_m','nominal_gdp_usd_m','share_gdp_pct'])
emit('4-nuclear-output-use',{'title':{'text':'The operating nuclear fleet kept producing more electricity','subtitle':['Selected US observations; later performance does not measure early investor returns.','Capacity factor unavailable for 1965 and 1970: those points are absent, not zero.']},'facet':{'row':{'field':'measure','type':'nominal','sort':['Electricity generated','Capacity factor'],'header':{'labelFontSize':14,'labelFontWeight':'bold','labelAngle':0,'title':None}}},'spec':{'width':560,'height':155,'mark':{'type':'line','point':True,'color':'#126782'},'encoding':{'x':{'field':'year','type':'quantitative','title':'Year','axis':{'format':'d'}},'y':{'field':'value','type':'quantitative','title':None,'scale':{'zero':True}},'tooltip':[{'field':'year'},{'field':'measure'},{'field':'value','type':'quantitative','format':'.1f'},{'field':'unit'}]}},'resolve':{'scale':{'y':'independent'}}},['year','value'])
